CREATE OR REPLACE FUNCTION public.audit_meal_log()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
   NEW.revision:=OLD.revision+1;
   IF NEW.details=OLD.details AND NEW.eaten<>OLD.eaten THEN NEW.details:='{}'; END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_meal_option()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE st text;
BEGIN
  SELECT v.status INTO st FROM plan_meals m JOIN plan_days d ON d.id=m.plan_day_id
  JOIN plan_versions v ON v.id=d.plan_version_id WHERE m.id=COALESCE(OLD.meal_id,NEW.meal_id);
  IF st IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'plan options are immutable'; END IF;
  IF TG_OP='UPDATE' AND OLD.meal_id<>NEW.meal_id THEN RAISE EXCEPTION 'option cannot move'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_plan_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND OLD.version_id<>NEW.version_id THEN RAISE EXCEPTION 'context cannot move'; END IF;
  IF (SELECT status FROM plan_versions WHERE id=COALESCE(OLD.version_id,NEW.version_id)) <> 'draft'
    THEN RAISE EXCEPTION 'plan context is immutable'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_plan_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'draft' THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'published'
     AND NEW.status = 'superseded'
     AND NEW.request_id = OLD.request_id
     AND NEW.version_number = OLD.version_number
     AND NEW.lock_version = OLD.lock_version
     AND NEW.published_at IS NOT DISTINCT FROM OLD.published_at THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'plan version is immutable';
END;
$function$

CREATE OR REPLACE FUNCTION public.record_meal_log_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 INSERT INTO meal_log_history(log_id,user_id,previous,current)
 VALUES(NEW.id,NEW.user_id,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW));
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_matches_session()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  session_expiry timestamptz;
BEGIN
  SELECT absolute_expires_at INTO session_expiry FROM sessions WHERE id = NEW.session_id;
  IF session_expiry IS NULL OR NEW.expires_at <> session_expiry THEN
    RAISE EXCEPTION 'refresh token cannot extend the session';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_non_draft_day()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  st text;
BEGIN
  SELECT status INTO st FROM plan_versions WHERE id = COALESCE(NEW.plan_version_id, OLD.plan_version_id);
  IF st IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'plan content is immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_non_draft_item()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  st text;
  parent_id uuid;
BEGIN
  parent_id := COALESCE(NEW.meal_id, OLD.meal_id);
  SELECT v.status INTO st
  FROM plan_meals m
  JOIN plan_days d ON d.id = m.plan_day_id
  JOIN plan_versions v ON v.id = d.plan_version_id
  WHERE m.id = parent_id;
  IF st IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'plan content is immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_non_draft_meal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  st text;
  day_id uuid;
BEGIN
  day_id := COALESCE(NEW.plan_day_id, OLD.plan_day_id);
  SELECT v.status INTO st
  FROM plan_days d
  JOIN plan_versions v ON v.id = d.plan_version_id
  WHERE d.id = day_id;
  IF st IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'plan content is immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_reward_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'weekly reward is immutable';
  END IF;
  IF NEW.id <> OLD.id
     OR NEW.user_id <> OLD.user_id
     OR NEW.request_id <> OLD.request_id
     OR NEW.week_start <> OLD.week_start
     OR NEW.amount_toman <> OLD.amount_toman
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'weekly reward is immutable';
  END IF;
  IF OLD.acknowledged_at IS NOT NULL AND NEW.acknowledged_at IS DISTINCT FROM OLD.acknowledged_at THEN
    RAISE EXCEPTION 'weekly reward is immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_submission_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('sabzine.anonymize', true) = 'on' THEN
    IF NEW.id <> OLD.id OR NEW.user_id <> OLD.user_id THEN
      RAISE EXCEPTION 'questionnaire submission is immutable';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'questionnaire submission is immutable';
END;
$function$

